# ---------------------------------------------------------------------------
# Helpers
# ---------------------------------------------------------------------------

def _arch_output(tasks: list[dict]) -> dict:
    """Build a realistic architecture run output_data dict."""
    return {
        "tasks":        tasks,
        "requirements": "Build a multi-agent LangGraph system.",
        "architecture": '{"nodes": ["planner", "executor"]}',
    }


def _base_task(title: str, order_index: int, pattern_refs: list[str] | None = None) -> dict:
    return {
        "title":       title,
        "description": f"Implement {title}.",
        "order_index": order_index,
        "pattern_refs": pattern_refs or [],
    }


async def _seed_arch_run(
    db: AsyncSession,
    *,
    project_id:  str,
    tasks:       list[dict],
    status:      str = "completed",
) -> Run:
    """Seed an architecture Run with the given task definitions."""
    run = Run(
        id            = str(uuid.uuid4()),
        project_id    = project_id,
        workflow_type = "architecture",
        status        = status,
        input_data    = {},
        output_data   = _arch_output(tasks) if status == "completed" else {},
        run_metadata  = {},
        started_at    = datetime.now(timezone.utc),
        finished_at   = datetime.now(timezone.utc) if status == "completed" else None,
    )
    db.add(run)
    await db.flush()
    return run


