class TestSingleTaskRun:

    @pytest.mark.asyncio
    async def test_single_task_happy_path(
        self, db, orchestrator, mock_openai
    ):
        """
        One task, base topology, all reviewers pass.
        Run â†’ COMPLETED.
        Task record â†’ COMPLETED with generated_files populated.
        """
        project_id = "proj-orch-001"
        arch_run   = await _seed_arch_run(
            db,
            project_id = project_id,
            tasks      = [_base_task("Planner Agent", 0)],
        )

        mock_openai.side_effect = [
            make_developer_response({"src/planner.py": "def plan(): pass"}),
            make_reviewer_pass_response(),
            make_reviewer_pass_response(),
            make_reviewer_pass_response(),
        ]

        result = await trigger_codegen_run(
            project_id          = project_id,
            architecture_run_id = arch_run.id,
            max_retries         = 3,
        )

        assert result["status"] in ("completed", "paused_hitl")

        # Verify Run record in DB
        run: Run = await db.get(Run, result["run_id"])
        assert run is not None
        output = run.output_data or {}
        assert len(output.get("completed_task_ids", [])) == 1
        assert output.get("failed_task_ids", []) == []

        # Verify Task record
        tasks = list((await db.execute(
            select(Task).where(Task.run_id == result["run_id"])
        )).scalars().all())
        assert len(tasks) == 1
        assert tasks[0].status == TaskStatus.COMPLETED.value
        assert "src/planner.py" in (tasks[0].generated_files or [])

    @pytest.mark.asyncio
    async def test_single_task_fails_run_still_bundles(
        self, db, orchestrator, mock_openai
    ):
        """
        Task exhausts all retries.
        Orchestrator still proceeds to bundling (bundle what exists).
        Run â†’ paused_hitl (bundle created, awaiting approval).
        Run.output_data["failed_task_ids"] contains the task ID.
        """
        project_id = "proj-orch-002"
        arch_run   = await _seed_arch_run(
            db,
            project_id = project_id,
            tasks      = [_base_task("Broken Task", 0)],
        )

        # All reviewer calls fail
        mock_openai.side_effect = (
            [
                make_developer_response({"src/broken.py": "BAD"}),
                make_reviewer_fail_response(feedback="Always fails."),
                make_reviewer_pass_response(),
                make_reviewer_pass_response(),
            ] * 4  # covers max_retries=2 (3 attempts)
        )

        result = await trigger_codegen_run(
            project_id          = project_id,
            architecture_run_id = arch_run.id,
            max_retries         = 2,
        )

        run: Run = await db.get(Run, result["run_id"])
        output = run.output_data or {}

        assert len(output.get("failed_task_ids", [])) == 1
        assert output.get("completed_task_ids", []) == []

        tasks = list((await db.execute(
            select(Task).where(Task.run_id == result["run_id"])
        )).scalars().all())
        assert tasks[0].status == TaskStatus.FAILED.value
        assert tasks[0].generated_files == []

    @pytest.mark.asyncio
    async def test_single_task_retry_count_persisted(
        self, db, orchestrator, mock_openai
    ):
        """
        Task retries twice before passing.
        Task.retry_count == 2 in the DB after completion.
        """
        project_id = "proj-orch-003"
        arch_run   = await _seed_arch_run(
            db,
            project_id = project_id,
            tasks      = [_base_task("Retry Task", 0)],
        )

        mock_openai.side_effect = [
            # Attempt 1: one reviewer fails
            make_developer_response({"src/a.py": "v1"}),
            make_reviewer_fail_response(feedback="Needs work."),
            make_reviewer_pass_response(),
            make_reviewer_pass_response(),
            # Attempt 2: one reviewer fails again
            make_developer_response({"src/a.py": "v2"}),
            make_reviewer_fail_response(feedback="Still needs work."),
            make_reviewer_pass_response(),
            make_reviewer_pass_response(),
            # Attempt 3: all pass
            make_developer_response({"src/a.py": "v3"}),
            make_reviewer_pass_response(),
            make_reviewer_pass_response(),
            make_reviewer_pass_response(),
        ]

        result = await trigger_codegen_run(
            project_id          = project_id,
            architecture_run_id = arch_run.id,
            max_retries         = 3,
        )

        tasks = list((await db.execute(
            select(Task).where(Task.run_id == result["run_id"])
        )).scalars().all())

        assert tasks[0].status      == TaskStatus.COMPLETED.value
        assert tasks[0].retry_count == 2


