class TestIdempotency:

    @pytest.mark.asyncio
    async def test_same_idempotency_key_returns_existing_run(
        self, db, orchestrator, mock_openai
    ):
        """
        Two trigger calls with the same idempotency_key.
        First creates and runs. Second returns the existing run immediately
        without invoking the graph again.
        """
        project_id       = "proj-idem-001"
        idempotency_key  = "idem-key-abc"

        arch_run = await _seed_arch_run(
            db,
            project_id = project_id,
            tasks      = [_base_task("Task", 0)],
        )

        mock_openai.side_effect = [
            make_developer_response({"src/a.py": "pass"}),
            make_reviewer_pass_response(),
            make_reviewer_pass_response(),
            make_reviewer_pass_response(),
        ]

        result_1 = await trigger_codegen_run(
            project_id          = project_id,
            architecture_run_id = arch_run.id,
            max_retries         = 3,
            idempotency_key     = idempotency_key,
        )

        # Second trigger â€” mock should NOT be called again
        mock_openai.reset_mock()
        result_2 = await trigger_codegen_run(
            project_id          = project_id,
            architecture_run_id = arch_run.id,
            max_retries         = 3,
            idempotency_key     = idempotency_key,
        )

        assert result_1["run_id"] == result_2["run_id"]
        mock_openai.assert_not_called()

    @pytest.mark.asyncio
    async def test_failed_run_allows_new_trigger_with_same_key(
        self, db, orchestrator, mock_openai
    ):
        """
        A failed run with idempotency_key does not block a fresh trigger.
        The check skips runs with status=failed.
        """
        project_id      = "proj-idem-002"
        idempotency_key = "idem-key-retry"

        arch_run = await _seed_arch_run(
            db,
            project_id = project_id,
            tasks      = [_base_task("Task", 0)],
        )

        # Seed a pre-existing FAILED run with the same idempotency key
        failed_run = Run(
            id            = str(uuid.uuid4()),
            project_id    = project_id,
            workflow_type = "codegen",
            status        = RunStatus.FAILED,
            run_metadata  = {"idempotency_key": idempotency_key},
            input_data    = {"architecture_run_id": arch_run.id},
            output_data   = {},
            started_at    = datetime.now(timezone.utc),
            finished_at   = datetime.now(timezone.utc),
        )
        db.add(failed_run)
        await db.flush()

        mock_openai.side_effect = [
            make_developer_response({"src/a.py": "pass"}),
            make_reviewer_pass_response(),
            make_reviewer_pass_response(),
            make_reviewer_pass_response(),
        ]

        result = await trigger_codegen_run(
            project_id          = project_id,
            architecture_run_id = arch_run.id,
            max_retries         = 3,
            idempotency_key     = idempotency_key,
        )

        # New run created â€” not the failed one
        assert result["run_id"] != failed_run.id


