class TestHITLGate:

    @pytest.mark.asyncio
    async def test_run_pauses_for_hitl_after_bundle(
        self, db, orchestrator, mock_openai
    ):
        """
        After all tasks complete and bundle is created,
        request_approval sets hitl_request_id.
        Run â†’ paused_hitl.
        """
        project_id = "proj-hitl-001"
        arch_run   = await _seed_arch_run(
            db,
            project_id = project_id,
            tasks      = [_base_task("Task", 0)],
        )

        mock_openai.side_effect = [
            make_developer_response({"src/a.py": "pass"}),
            make_reviewer_pass_response(),
            make_reviewer_pass_response(),
            make_reviewer_pass_response(),
        ]

        result = await trigger_codegen_run(
            project_id          = project_id,
            architecture_run_id = arch_run.id,
            max_retries         = 3,
        )

        assert result["status"] == "paused_hitl"
        run: Run = await db.get(Run, result["run_id"])
        output = run.output_data or {}
        assert output.get("hitl_request_id") is not None
        assert run.status.value == "paused_hitl"

    @pytest.mark.asyncio
    async def test_resume_approved_marks_run_completed(
        self, db, orchestrator, mock_openai
    ):
        """
        After trigger puts run into paused_hitl,
        resume_codegen_run(approved=True) â†’ Run â†’ COMPLETED.
        """
        project_id = "proj-hitl-002"
        arch_run   = await _seed_arch_run(
            db,
            project_id = project_id,
            tasks      = [_base_task("Task", 0)],
        )

        mock_openai.side_effect = [
            make_developer_response({"src/a.py": "pass"}),
            make_reviewer_pass_response(),
            make_reviewer_pass_response(),
            make_reviewer_pass_response(),
        ]

        trigger_result = await trigger_codegen_run(
            project_id          = project_id,
            architecture_run_id = arch_run.id,
            max_retries         = 3,
        )
        run_id = trigger_result["run_id"]
        assert trigger_result["status"] == "paused_hitl"

        resume_result = await resume_codegen_run(
            run_id     = run_id,
            project_id = project_id,
            approved   = True,
        )

        assert resume_result["status"] == "completed"
        run: Run = await db.get(Run, run_id)
        assert run.status.value == "completed"
        output = run.output_data or {}
        assert output.get("approved") is True

    @pytest.mark.asyncio
    async def test_resume_rejected_marks_run_failed(
        self, db, orchestrator, mock_openai
    ):
        """
        resume_codegen_run(approved=False, feedback=...) â†’ Run â†’ FAILED.
        Rejection reason stored in output_data["rejected_reason"].
        """
        project_id = "proj-hitl-003"
        arch_run   = await _seed_arch_run(
            db,
            project_id = project_id,
            tasks      = [_base_task("Task", 0)],
        )

        mock_openai.side_effect = [
            make_developer_response({"src/a.py": "pass"}),
            make_reviewer_pass_response(),
            make_reviewer_pass_response(),
            make_reviewer_pass_response(),
        ]

        trigger_result = await trigger_codegen_run(
            project_id          = project_id,
            architecture_run_id = arch_run.id,
            max_retries         = 3,
        )
        run_id = trigger_result["run_id"]

        resume_result = await resume_codegen_run(
            run_id     = run_id,
            project_id = project_id,
            approved   = False,
            feedback   = "Code quality below threshold.",
        )

        assert resume_result["status"] == "failed"
        run: Run = await db.get(Run, run_id)
        assert run.status.value  == "failed"
        assert run.error         == "Code quality below threshold."
        output = run.output_data or {}
        assert output.get("rejected_reason") == "Code quality below threshold."

    @pytest.mark.asyncio
    async def test_resume_non_paused_run_raises(
        self, db, orchestrator, mock_openai
    ):
        """
        Calling resume on a run that is not paused_hitl raises ValueError.
        """
        project_id = "proj-hitl-004"

        # Seed a COMPLETED run directly â€” no trigger needed
        completed_run = Run(
            id            = str(uuid.uuid4()),
            project_id    = project_id,
            workflow_type = "codegen",
            status        = RunStatus.COMPLETED,
            input_data    = {},
            output_data   = {},
            run_metadata  = {},
            started_at    = datetime.now(timezone.utc),
            finished_at   = datetime.now(timezone.utc),
        )
        db.add(completed_run)
        await db.flush()

        with pytest.raises(ValueError, match="not paused"):
            await resume_codegen_run(
                run_id     = completed_run.id,
                project_id = project_id,
                approved   = True,
            )


