# ===========================================================================
# DB STATE ACCURACY
# ===========================================================================

class TestDBStateAccuracy:

    @pytest.mark.asyncio
    async def test_run_output_data_accurate_after_completion(
        self, db, orchestrator, mock_openai
    ):
        """
        After a full two-task run where one passes and one fails,
        Run.output_data contains accurate task ID lists, bundle_path,
        and hitl_request_id.
        """
        project_id = "proj-db-001"
        arch_run   = await _seed_arch_run(
            db,
            project_id = project_id,
            tasks      = [
                _base_task("Good", 0),
                _base_task("Bad",  1),
            ],
        )

        mock_openai.side_effect = [
            # Good task passes
            make_developer_response({"src/good.py": "pass"}),
            make_reviewer_pass_response(),
            make_reviewer_pass_response(),
            make_reviewer_pass_response(),
            # Bad task always fails (max_retries=0 â†’ 1 attempt only)
            make_developer_response({"src/bad.py": "BAD"}),
            make_reviewer_fail_response(feedback="Always."),
            make_reviewer_pass_response(),
            make_reviewer_pass_response(),
        ]

        result = await trigger_codegen_run(
            project_id          = project_id,
            architecture_run_id = arch_run.id,
            max_retries         = 0,
        )

        run: Run = await db.get(Run, result["run_id"])
        output   = run.output_data or {}

        assert len(output["completed_task_ids"]) == 1
        assert len(output["failed_task_ids"])    == 1
        assert output["bundle_path"] is not None
        assert output["hitl_request_id"] is not None

    @pytest.mark.asyncio
    async def test_task_feedback_persisted_on_failure(
        self, db, orchestrator, mock_openai
    ):
        """
        When a task fails, the aggregated reviewer feedback is stored
        in Task.feedback so the caller can see why it failed.
        """
        project_id = "proj-db-002"
        arch_run   = await _seed_arch_run(
            db,
            project_id = project_id,
            tasks      = [_base_task("Failing Task", 0)],
        )

        feedback_text = "Security reviewer: no input sanitisation found."
        mock_openai.side_effect = [
            make_developer_response({"src/a.py": "pass"}),
            make_reviewer_pass_response(),
            make_reviewer_pass_response(),
            make_reviewer_fail_response(feedback=feedback_text),
        ]

        result = await trigger_codegen_run(
            project_id          = project_id,
            architecture_run_id = arch_run.id,
            max_retries         = 0,
        )

        tasks = list((await db.execute(
            select(Task).where(Task.run_id == result["run_id"])
        )).scalars().all())

        assert tasks[0].status   == TaskStatus.FAILED.value
        assert feedback_text in (tasks[0].feedback or "")







